'use client'

import { ChevronDown } from 'lucide-react'
import { Accordion as AccordionPrimitive } from 'radix-ui'
import * as React from 'react'

import { cn } from '../../../lib/utils/cn'
import { getExplicitTabIndex } from '../../../lib/utils/getExplicitTabIndex'

const Accordion = AccordionPrimitive.Root

const AccordionItem = React.forwardRef<
  React.ElementRef<typeof AccordionPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Item>
>(({ className, ...props }, ref) => (
  <AccordionPrimitive.Item ref={ref} className={cn('border-b', className)} {...props} />
))
AccordionItem.displayName = 'AccordionItem'

const AccordionTrigger = React.forwardRef<
  React.ElementRef<typeof AccordionPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Trigger> & {
    focusVariant?: 'ring' | 'inset'
    hideIcon?: boolean
  }
>(
  (
    { className, children, focusVariant = 'inset', hideIcon, disabled, tabIndex, ...props },
    ref
  ) => {
    const computedTabIndex = getExplicitTabIndex(tabIndex, disabled)

    return (
      <AccordionPrimitive.Header asChild>
        <div className="flex w-full">
          <AccordionPrimitive.Trigger
            ref={ref}
            className={cn(
              'cursor-pointer flex flex-1 gap-2 items-center justify-between py-4 text-left',
              'font-medium hover:underline',
              '[&[data-state=open]>svg]:rotate-180',
              focusVariant === 'ring' && 'rounded-md',
              className,
              focusVariant === 'ring' ? 'focus-ring' : 'relative focus-inset'
            )}
            {...props}
            disabled={disabled}
            tabIndex={computedTabIndex}
          >
            {children}
            {!hideIcon && (
              <ChevronDown
                aria-hidden="true"
                className={cn(
                  'h-4 w-4 shrink-0',
                  'transition-transform duration-200',
                  'motion-reduce:transition-none motion-reduce:duration-0'
                )}
              />
            )}
          </AccordionPrimitive.Trigger>
        </div>
      </AccordionPrimitive.Header>
    )
  }
)
AccordionTrigger.displayName = AccordionPrimitive.Trigger.displayName

const AccordionContent = React.forwardRef<
  React.ElementRef<typeof AccordionPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Content>
>(({ className, children, ...props }, ref) => (
  <AccordionPrimitive.Content
    ref={ref}
    className={cn(
      'overflow-hidden text-sm',
      'transition-all motion-reduce:transition-none',
      'data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down',
      'motion-reduce:animate-none',
      className
    )}
    {...props}
  >
    <div className="pb-4 pt-0">{children}</div>
  </AccordionPrimitive.Content>
))
AccordionContent.displayName = AccordionPrimitive.Content.displayName

export { Accordion, AccordionContent, AccordionItem, AccordionTrigger }
